#include <zephyr/ztest/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/timing/timing.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define THREAD_PRIORITY 5

static K_THREAD_STACK_DEFINE(thread_stack, STACK_SIZE);
static struct k_thread thread_data;

static volatile bool thread_ran;

void thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    thread_ran = true;
    k_thread_abort(k_current_get());
}

/**
 * @brief Test setting and getting thread deadline
 *
 * @details This test verifies that k_thread_deadline_set and
 *          k_thread_deadline_get work as expected.
 *
 * @ingroup kernel_sched_tests
 */
ZTEST(deadline_api, test_deadline_set_get)
{
    k_timeout_t deadline_val = K_MSEC(100);
    k_timeout_t retrieved_deadline;

    k_thread_deadline_set(k_current_get(), deadline_val);
    retrieved_deadline = k_thread_deadline_get(k_current_get());

    zassert_true(K_TIMEOUT_EQ(deadline_val, retrieved_deadline), "Deadline set and retrieved values do not match");
}

/**
 * @brief Test deadline scheduling basic functionality
 *
 * @details This test creates a thread, sets its deadline, and verifies
 *          that it runs within the expected timeframe.
 *
 * @ingroup kernel_sched_tests
 */
ZTEST(deadline_api, test_deadline_scheduling_basic)
{
    k_timeout_t deadline_val = K_MSEC(50);
    timing_t start_time, end_time;
    uint64_t cycles_spent;
    uint64_t ns_spent;

    thread_ran = false;

    k_thread_create(&thread_data, thread_stack, STACK_SIZE,
                    thread_entry, NULL, NULL, NULL,
                    THREAD_PRIORITY, 0, K_NO_WAIT);

    k_thread_deadline_set(&thread_data, deadline_val);

    start_time = timing_counter_get();

    /* Wait for the thread to run and abort itself */
    k_thread_join(&thread_data, K_FOREVER);

    end_time = timing_counter_get();

    zassert_true(thread_ran, "Thread did not run");

    cycles_spent = timing_cycles_get(&start_time, &end_time);
    ns_spent = timing_cycles_to_ns(cycles_spent);

    /* The thread should run before its deadline expires. */
    /* Allow some margin for scheduling overhead. */
    zassert_true(ns_spent < k_timeout_to_ns_floor64(deadline_val) + 1000000, "Thread ran too late");
}

/**
 * @brief Test deadline wrapper function
 *
 * @details This test uses a wrapper to set the deadline and ensures
 *          the correct function is called.
 *
 * @ingroup kernel_sched_tests
 */
static void _suite_deadline_test_deadline_wrapper(void)
{
    k_timeout_t deadline_val = K_MSEC(100);
    /* This is the line that had the typo */
    k_thread_deadline_set(k_current_get(), deadline_val);
    zassert_true(K_TIMEOUT_EQ(deadline_val, k_thread_deadline_get(k_current_get())),
                 "Deadline set via wrapper and retrieved values do not match");
}

ZTEST(deadline_api, test_deadline_wrapper)
{
    _suite_deadline_test_deadline_wrapper();
}

ZTEST_SUITE(deadline_api, NULL, NULL, NULL, NULL, NULL);
